int f(int n){
int p = 0;
int q = 1;
int r = 0;
int h = 0;
r = n;
h = 0;
if (q > n)
{
  while (((p * p) + (r * q)) == (n * q))
  {
    if (((4 * (q / 4)) == q) && ((2 * (p / 2)) == p))
    {
      q = q / 4;
      h = p + q;
      p = p / 2;
      if (r >= h)
      {
        p = p + q;
        r = r - h;
      }
    }
  }

}

return 0;
}
